always-actions.script:
const myPartyId = ec.user.userAccount?.partyId
const CE = 'mantle.party.communication.CommunicationEvent'
const partyTo = (event) => event != null && !!myPartyId && (event.fromPartyId == myPartyId || event.toPartyId == myPartyId ||
        ec.entity.find('mantle.party.communication.CommunicationEventParty').condition({communicationEventId: event.communicationEventId,
            partyId: myPartyId}).count() > 0)
if (communicationEventId) {
    const event = ec.entity.find(CE).condition('communicationEventId', communicationEventId).one()
    if (!partyTo(event)) throw new Error(`Message ${communicationEventId} is not one of yours`)
}
if (rootCommEventId) {
    const root = ec.entity.find(CE).condition('communicationEventId', rootCommEventId).one()
    if (!partyTo(root) && !Array.from(ec.entity.find(CE).condition('rootCommEventId', rootCommEventId).limit(200).list()).some(partyTo))
        throw new Error(`Message thread ${rootCommEventId} is not one of yours`)
}
